//! 🎥️ Handcrafted MP4 borrowed roles admit all relational cells before owned binding.
use super::*;
use semio_framework_dsl_record::{DslField,FieldValue as F,RecordValue as R};
use semio_framework_value::NativeDecodeControl as N;
use store::sqlite_snapshot::{SqliteDatabaseLimits,artifact::RowWriter};
const WIDTHS:[(&str,usize);23]=[("mp4_document",2),("mp4_ftyp",3),("mp4_compatible_brand",4),("mp4_movie",10),("mp4_movie_matrix",4),("mp4_track",7),("mp4_codec",3),("mp4_avc_sps",4),("mp4_avc_pps",4),("mp4_avc_extension",4),("mp4_avc_sps_extension",4),("mp4_hevc_config",16),("mp4_hevc_array",5),("mp4_hevc_nal",4),("mp4_track_metadata",14),("mp4_track_matrix",4),("mp4_edit",7),("mp4_visual_sample_entry",13),("mp4_color",6),("mp4_pixel_aspect_ratio",3),("mp4_bitrate",4),("mp4_chunk_sample_count",4),("mp4_sample",7)];
fn add(a:usize,b:usize)->Result<usize,ValueError>{a.checked_add(b).ok_or_else(||ownership("MP4 semantic cell extent overflow"))}
pub(super) fn extent(limits:SqliteDatabaseLimits)->Result<(),ValueError>{let mut bytes=0usize;for statement in Mp4Snapshot::SQLITE_SCHEMA.split(';'){bytes=add(bytes,statement.trim().len())?;}for(name,_)in WIDTHS{bytes=add(bytes,name.len())?;}if bytes.max(Mp4Snapshot::SQLITE_SCHEMA.len())>limits.max_schema_bytes{return Err(ownership("MP4 authored schema exceeds caller bytes"))}if limits.max_tables<WIDTHS.len()||WIDTHS.iter().any(|(_,width)|*width>limits.max_columns)||limits.max_rows<12{return Err(work("MP4 authored relational extent exceeds caller limits"))}Ok(())}
pub(super) fn typed(snapshot:&Mp4Snapshot,phase:SqliteSnapshotPhase,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{extent(control.limits())?;let mut out=RowWriter::borrowed(control,phase)?;super::visit_rows(snapshot,&mut out)?;out.finish_borrowed()}
fn exact(record:&R,count:u16)->Result<(),ValueError>{if record.fields.keys().copied().eq(0..count){Ok(())}else{Err(invalid("MP4 native record requires every authored field slot"))}}
fn field(record:&R,id:u16)->Result<&F,ValueError>{record.get(id).ok_or_else(||invalid("MP4 native authored field is missing"))}
fn record(value:&F,count:u16)->Result<&R,ValueError>{let F::Record(value)=value else{return Err(invalid("MP4 literal Record required"))};exact(value,count)?;Ok(value)}
fn optional(value:&F,count:u16)->Result<Option<&R>,ValueError>{if matches!(value,F::Absent){Ok(None)}else{record(value,count).map(Some)}}
fn items(value:&F)->Result<&[F],ValueError>{match value{F::List(values)=>Ok(values),_=>Err(invalid("MP4 literal List required"))}}
fn uint(value:&F,maximum:u64)->Result<u64,ValueError>{match value{F::UInt(value)if *value<=maximum=>Ok(*value),_=>Err(invalid("MP4 native unsigned field differs from declared width"))}}
fn signed(value:&F,minimum:i64,maximum:i64)->Result<(),ValueError>{if matches!(value,F::Int(value)if *value>=minimum&&*value<=maximum){Ok(())}else{Err(invalid("MP4 native signed field differs from declared width"))}}
fn boolean(value:&F)->Result<(),ValueError>{if matches!(value,F::Bool(_)){Ok(())}else{Err(invalid("MP4 literal Bool required"))}}
fn text(value:&F,n:&mut N<'_>)->Result<usize,ValueError>{let F::Text(value)=value else{return Err(invalid("MP4 lexical field requires Text"))};n.scoped_stage(|n|{n.begin_stage(value.len())?;for part in value.as_bytes().chunks(256){n.advance(part.len())?;}Ok::<_,ValueError>(())})?;Ok(value.len())}
fn optional_text(value:&F,n:&mut N<'_>)->Result<usize,ValueError>{if matches!(value,F::Absent){Ok(0)}else{text(value,n)}}
fn decimal(value:&F)->Result<usize,ValueError>{let mut value=uint(value,u64::MAX)?;let mut digits=1;while value>=10{value/=10;digits+=1;}Ok(digits)}
fn octets(value:&F,n:&mut N<'_>)->Result<usize,ValueError>{let values=items(value)?;n.scoped_stage(|n|{n.begin_stage(values.len())?;for value in values{uint(value,u64::from(u8::MAX))?;n.step()?;}Ok::<_,ValueError>(())})?;Ok(values.len())}
fn blob(value:&F,n:&mut N<'_>)->Result<usize,ValueError>{let F::Bytes64(values)=value else{return Err(invalid("MP4 sample data requires intrinsic Bytes64"))};n.scoped_stage(|n|{n.begin_stage(values.len())?;for part in values.chunks(256){n.advance(part.len())?;}Ok::<_,ValueError>(())})?;Ok(values.len())}
fn unsigned(record:&R,ids:&[u16],maximum:u64)->Result<(),ValueError>{for id in ids{uint(field(record,*id)?,maximum)?;}Ok(())}
fn signed_fields(record:&R,ids:&[u16],minimum:i64,maximum:i64)->Result<(),ValueError>{for id in ids{signed(field(record,*id)?,minimum,maximum)?;}Ok(())}
struct Census{limits:SqliteDatabaseLimits,rows:usize,bytes:usize}
impl Census{fn row(&mut self,bytes:usize,n:&mut N<'_>)->Result<(),ValueError>{let rows=self.rows.checked_add(1).ok_or_else(||work("MP4 semantic row count overflow"))?;let total=add(self.bytes,bytes)?;if rows>self.limits.max_rows{return Err(work("MP4 semantic rows exceed caller limit"))}if total>self.limits.max_value_bytes{return Err(ownership("MP4 semantic cells exceed caller bytes"))}n.step()?;self.rows=rows;self.bytes=total;Ok(())}}
fn matrix(value:&F,c:&mut Census,n:&mut N<'_>)->Result<(),ValueError>{let F::Tuple(values)=value else{return Err(invalid("MP4 matrix requires literal Tuple"))};if values.len()!=9{return Err(invalid("MP4 matrix requires nine signed components"))}for value in values{signed(value,i64::from(i32::MIN),i64::from(i32::MAX))?;c.row(32,n)?;}Ok(())}
fn nals(value:&F,c:&mut Census,n:&mut N<'_>)->Result<(),ValueError>{for value in items(value)?{c.row(add(24,octets(value,n)?)?,n)?;}Ok(())}
fn codec(value:&F,c:&mut Census,n:&mut N<'_>)->Result<(),ValueError>{let value=record(value,6)?;uint(field(value,3)?,u64::from(u8::MAX))?;let format=<Mp4CodecFormat as DslField>::from_value_controlled(field(value,0)?,n)?;c.row(add(16,format.fourcc().len())?,n)?;nals(field(value,1)?,c,n)?;nals(field(value,2)?,c,n)?;
 if let Some(extension)=optional(field(value,4)?,4)?{unsigned(extension,&[0,1,2],u64::from(u8::MAX))?;c.row(32,n)?;nals(field(extension,3)?,c,n)?;}
 if let Some(hevc)=optional(field(value,5)?,16)?{unsigned(hevc,&[0,2,5,7,8,9,10,12,13],u64::from(u8::MAX))?;unsigned(hevc,&[3],u64::from(u32::MAX))?;unsigned(hevc,&[6,11],u64::from(u16::MAX))?;boolean(field(hevc,1)?)?;boolean(field(hevc,14)?)?;c.row(add(120,decimal(field(hevc,4)?)?)?,n)?;for array in items(field(hevc,15)?)?{let array=record(array,3)?;boolean(field(array,0)?)?;uint(field(array,1)?,u64::from(u8::MAX))?;c.row(40,n)?;nals(field(array,2)?,c,n)?;}}Ok(())
}
fn metadata(value:&F,c:&mut Census,n:&mut N<'_>)->Result<(),ValueError>{let value=record(value,19)?;unsigned(value,&[2],u64::from(u32::MAX))?;unsigned(value,&[12],u64::from(u16::MAX))?;signed_fields(value,&[4,5,6],i64::from(i16::MIN),i64::from(i16::MAX))?;let mut bytes=48;for id in[0,1,3,8,9,10]{bytes=add(bytes,decimal(field(value,id)?)?)?;}for id in[11,13]{bytes=add(bytes,text(field(value,id)?,n)?)?;}c.row(bytes,n)?;matrix(field(value,7)?,c,n)?;
 for edit in items(field(value,14)?)?{let edit=record(edit,4)?;signed(field(edit,1)?,i64::MIN,i64::MAX)?;signed_fields(edit,&[2,3],i64::from(i16::MIN),i64::from(i16::MAX))?;c.row(add(48,decimal(field(edit,0)?)?)?,n)?;}
 let visual=record(field(value,15)?,12)?;unsigned(visual,&[0,1,2,8,10],u64::from(u16::MAX))?;unsigned(visual,&[3,4,5,6,7],u64::from(u32::MAX))?;signed(field(visual,11)?,i64::from(i16::MIN),i64::from(i16::MAX))?;c.row(add(96,text(field(visual,9)?,n)?)?,n)?;
 if let Some(color)=optional(field(value,16)?,5)?{unsigned(color,&[1,2,3],u64::from(u16::MAX))?;let flag=field(color,4)?;let flag=if matches!(flag,F::Absent){0}else{boolean(flag)?;8};c.row(add(add(32,text(field(color,0)?,n)?)?,flag)?,n)?;}
 if let Some(aspect)=optional(field(value,17)?,2)?{unsigned(aspect,&[0,1],u64::from(u32::MAX))?;c.row(24,n)?;}
 if let Some(bitrate)=optional(field(value,18)?,3)?{unsigned(bitrate,&[0,1,2],u64::from(u32::MAX))?;c.row(32,n)?;}Ok(())
}
pub(super) fn borrowed(root:&R,limits:SqliteDatabaseLimits,n:&mut N<'_>)->Result<(),ValueError>{extent(limits)?;n.scoped_stage(|n|{n.begin_stage(0)?;exact(root,4)?;let mut c=Census{limits,rows:0,bytes:0};c.row(add(8,text(field(root,0)?,n)?)?,n)?;
 let ftyp=record(field(root,1)?,3)?;uint(field(ftyp,1)?,u64::from(u32::MAX))?;c.row(add(16,text(field(ftyp,0)?,n)?)?,n)?;for brand in items(field(ftyp,2)?)?{c.row(add(24,text(brand,n)?)?,n)?;}
 let movie=record(field(root,2)?,10)?;unsigned(movie,&[2,7],u64::from(u32::MAX))?;signed(field(movie,4)?,i64::from(i32::MIN),i64::from(i32::MAX))?;signed(field(movie,5)?,i64::from(i16::MIN),i64::from(i16::MAX))?;let mut bytes=40;for id in[0,1,3]{bytes=add(bytes,decimal(field(movie,id)?)?)?;}for id in[8,9]{bytes=add(bytes,optional_text(field(movie,id)?,n)?)?;}c.row(bytes,n)?;matrix(field(movie,6)?,&mut c,n)?;
 for value in items(field(root,3)?)?{let value=record(value,8)?;unsigned(value,&[0,1,3,4],u64::from(u32::MAX))?;c.row(56,n)?;codec(field(value,2)?,&mut c,n)?;metadata(field(value,5)?,&mut c,n)?;for count in items(field(value,6)?)?{uint(count,u64::from(u32::MAX))?;c.row(32,n)?;}for sample in items(field(value,7)?)?{let sample=record(sample,4)?;uint(field(sample,1)?,u64::from(u32::MAX))?;signed(field(sample,2)?,i64::from(i32::MIN),i64::from(i32::MAX))?;boolean(field(sample,3)?)?;c.row(add(48,blob(field(sample,0)?,n)?)?,n)?;}}
 n.checkpoint()
})}
